import AppKit
import CmuxNextUpdater

/// The About panel's credits for one app bundle: one link to its bundled
/// third-party notices (`THIRD_PARTY_LICENSES.md`, generated by
/// scripts/cmux-next/generate-third-party-notices.sh), so the licenses that
/// cmux ships under (MIT credits such as t3code included) are one click from
/// About cmux. A DEV build made with the explicit `CMUX_NEXT_SKIP_RB_HOST=1`
/// opt-out also says so here: embed-remote-browser-host.sh writes
/// `RemoteBrowserHostOptOut.txt` into the bundle's resources.
///
/// It also lists what is in this build (Leo 2026-11-26: "hm do we display which prs go into which
/// nightly maybe that'd be useful per thing?"): the PRs its signed notes name, by area, each linked.
struct AboutPanelCredits {
    let bundle: Bundle
    /// This build's PRs (``UpdaterService/currentBuildPullRequests()``); nil or empty lists none.
    var pullRequests: BuildPullRequests?

    static var pullRequestsTitle: String {
        String(localized: "about.credits.prs.title", defaultValue: "What's in this build", table: "Windows", bundle: .module.inAppLanguage)
    }

    static var pullRequestsOther: String {
        String(localized: "about.credits.prs.other", defaultValue: "Other", table: "Windows", bundle: .module.inAppLanguage)
    }

    static func pullRequestsInternal(_ count: Int) -> String {
        let format = String(localized: "about.credits.prs.internal", defaultValue: "Internal (CI and tooling): %@", table: "Windows",
                            bundle: .module.inAppLanguage)
        return String(format: format, String(count))
    }

    /// The link text.
    static var title: String {
        String(localized: "about.credits.licenses", defaultValue: "Third-Party Licenses", table: "Windows", bundle: .module.inAppLanguage)
    }

    /// The line shown when the build opted out of the remote browser host.
    static var remoteBrowserHostOptOut: String {
        String(
            localized: "about.credits.remoteBrowserHostOptOut",
            defaultValue: "Built without the remote browser host (CMUX_NEXT_SKIP_RB_HOST=1)",
            table: "Windows",
            bundle: .module.inAppLanguage
        )
    }

    /// The notices file inside the bundle, when it has one.
    var licensesURL: URL? {
        bundle.url(forResource: "THIRD_PARTY_LICENSES", withExtension: "md")
    }

    /// Whether the build opted out of embedding the remote browser host.
    var remoteBrowserHostOptedOut: Bool {
        bundle.url(forResource: "RemoteBrowserHostOptOut", withExtension: "txt") != nil
    }

    /// Credits text: a link to the notices file and the opt-out line, each
    /// when present; nil when neither is.
    var credits: NSAttributedString? {
        let centered = NSMutableParagraphStyle()
        centered.alignment = .center
        let font = NSFont.systemFont(ofSize: NSFont.smallSystemFontSize)
        var lines: [NSAttributedString] = []
        if let url = licensesURL {
            lines.append(NSAttributedString(string: Self.title, attributes: [.link: url, .font: font, .paragraphStyle: centered]))
        }
        if remoteBrowserHostOptedOut {
            lines.append(NSAttributedString(string: Self.remoteBrowserHostOptOut, attributes: [
                .font: font,
                .foregroundColor: NSColor.systemOrange,
                .paragraphStyle: centered,
            ]))
        }
        lines += pullRequestLines(font: font, centered: centered)
        guard !lines.isEmpty else { return nil }
        let out = NSMutableAttributedString()
        for (index, line) in lines.enumerated() {
            if index > 0 { out.append(NSAttributedString(string: "\n", attributes: [.font: font, .paragraphStyle: centered])) }
            out.append(line)
        }
        return out
    }

    /// The build's PRs: a blank line, the heading with the count, then each area's name and its PRs
    /// ("#30 Title, author"), each linked to its page; the internal count last.
    private func pullRequestLines(font: NSFont, centered: NSParagraphStyle) -> [NSAttributedString] {
        guard let list = pullRequests, !list.isEmpty else { return [] }
        let bold = NSFont.boldSystemFont(ofSize: NSFont.smallSystemFontSize)
        let quiet: [NSAttributedString.Key: Any] = [.font: font, .foregroundColor: NSColor.secondaryLabelColor, .paragraphStyle: centered]
        var lines = [NSAttributedString(string: "", attributes: [.font: font, .paragraphStyle: centered]),
                     NSAttributedString(string: "\(Self.pullRequestsTitle) · \(list.count)", attributes: [.font: bold, .paragraphStyle: centered])]
        for group in list.groups {
            lines.append(NSAttributedString(string: group.area ?? Self.pullRequestsOther, attributes: quiet))
            for item in group.items {
                let text = ["#\(item.pr) \(item.title)", item.author].compactMap { $0 }.joined(separator: ", ")
                lines.append(NSAttributedString(string: text, attributes: [.link: item.url, .font: font, .paragraphStyle: centered]))
            }
        }
        if list.internalCount > 0 { lines.append(NSAttributedString(string: Self.pullRequestsInternal(list.internalCount), attributes: quiet)) }
        return lines
    }
}
